// STEP 1 - PARSE INTENT
// Lightweight keyword-based intent parser.
// Swap this for an LLM node (OpenAI/Claude) later for true NL understanding -
// keep this rule-based version as a reliable fallback for the demo.

const body = $input.first().json.body || $input.first().json;
const query = (body.query || 'find the highest heat-risk zones').toLowerCase();
const city = body.city || 'Phoenix, AZ';

let intent = 'investigate';
if (query.includes('compare')) intent = 'compare';
else if (query.includes('monitor') || query.includes('alert')) intent = 'monitor';
else if (query.includes('why') || query.includes('explain')) intent = 'explain';
else if (query.includes('plan') || query.includes('recommend') || query.includes('should')) intent = 'plan';

return [{
  json: {
    original_query: query,
    city,
    intent,
    agent_activity: ['Parsed user objective', `Detected intent: ${intent}`, `Target city: ${city}`]
  }
}];

