// STEP 3 - RISK ENGINE
// Our own transparent, documented Heat Risk Score (NOT provided by FortyGuard):
//   Temperature            35%
//   Exceedance duration    25%
//   Persistence            20%
//   Environmental stress   10%
//   Time-of-day exposure   10%
// All sub-scores normalized 0-100 before weighting.

function clamp(n, lo, hi) { return Math.max(lo, Math.min(hi, n)); }
function norm(value, min, max) { return clamp(((value - min) / (max - min)) * 100, 0, 100); }

function timeOfDayScore(hhmm) {
  const hour = parseInt(hhmm.split(':')[0], 10);
  if (hour >= 14 && hour <= 16) return 100;
  if ((hour >= 13 && hour < 14) || (hour > 16 && hour <= 17)) return 80;
  if ((hour >= 12 && hour < 13) || (hour > 17 && hour <= 18)) return 60;
  return 40;
}

const prev = $input.first().json;

const scored = prev.zones.map(z => {
  const tempScore = norm(z.temperature_c, 35, 48);
  const exceedScore = norm(z.exceedance_hours, 0, 6);
  const persistScore = norm(z.persistence_hours, 0, 5);
  const envScore = clamp(
    norm(z.environmental.heat_index_c - z.temperature_c, 0, 6) * 0.5 +
    norm(z.environmental.aqi, 0, 150) * 0.3 +
    norm(z.environmental.solar_irradiance_wm2, 600, 1000) * 0.2,
    0, 100
  );
  const timeScore = timeOfDayScore(z.time_of_measure);

  const riskScore = Math.round(
    tempScore * 0.35 +
    exceedScore * 0.25 +
    persistScore * 0.20 +
    envScore * 0.10 +
    timeScore * 0.10
  );

  let level = 'LOW';
  if (riskScore > 80) level = 'CRITICAL';
  else if (riskScore > 60) level = 'VERY HIGH';
  else if (riskScore > 40) level = 'HIGH';
  else if (riskScore > 20) level = 'MODERATE';

  return {
    ...z,
    scores: {
      temperature: Math.round(tempScore),
      exceedance: Math.round(exceedScore),
      persistence: Math.round(persistScore),
      environmental: Math.round(envScore),
      time_of_day: Math.round(timeScore)
    },
    risk_score: riskScore,
    risk_level: level
  };
});

return [{
  json: {
    ...prev,
    zones: scored,
    agent_activity: [...prev.agent_activity, 'Calculated heat exceedance', 'Calculated heat persistence', 'Retrieved environmental parameters', `Scored ${scored.length} zones using weighted Heat Risk formula`]
  }
}];

// STEP 4 - RANK + EXPLAIN
// Ranks zones by risk_score and generates a plain-language reason
// by pointing to whichever sub-scores are actually driving the result.

const prev = $input.first().json;
const ranked = [...prev.zones].sort((a, b) => b.risk_score - a.risk_score);

function explain(z) {
  const reasons = [];
  if (z.scores.temperature >= 70) reasons.push('elevated ambient temperature');
  if (z.scores.exceedance >= 70) reasons.push('a long duration above the safe heat threshold');
  if (z.scores.persistence >= 70) reasons.push('sustained, continuous heat rather than a brief spike');
  if (z.scores.environmental >= 70) reasons.push('added environmental stress (heat index, air quality, solar load)');
  if (z.scores.time_of_day >= 80) reasons.push('a peak that falls during active operating hours');
  if (reasons.length === 0) reasons.push('moderate readings across all risk factors');
  return `${z.name} is ${z.risk_level.toLowerCase()} risk because it combines ${reasons.join(', ')}.`;
}

const explained = ranked.map((z, i) => ({ ...z, rank: i + 1, explanation: explain(z) }));

return [{
  json: {
    ...prev,
    zones: explained,
    top_zone: explained[0],
    agent_activity: [...prev.agent_activity, `Ranked ${explained.length} zones by risk score`, `Identified top priority zone: ${explained[0].name} (${explained[0].risk_score}/100)`]
  }
}];

// STEP 5 - ACTION PLAN
// Maps the top-ranked zone's dominant risk factor to concrete recommendations.
// Swap/extend with an LLM node for richer, more varied language if desired -
// this rule-based version guarantees a sensible answer even with no AI key.

const prev = $input.first().json;
const top = prev.top_zone;

const actions = [];
if (top.scores.time_of_day >= 80) actions.push('Shift heavy outdoor work to before 13:00 or after 17:00');
if (top.scores.persistence >= 70) actions.push('Increase worker break frequency and shaded recovery time');
if (top.scores.temperature >= 70 || top.scores.exceedance >= 70) actions.push('Deploy cooling stations / shade structures at this location first');
if (top.scores.environmental >= 70) actions.push('Monitor air quality alongside heat - combined stress raises health risk');
if (actions.length === 0) actions.push('Continue routine monitoring; no immediate intervention required');

const plan = {
  priority_zone: top.name,
  priority_level: top.risk_level,
  recommended_actions: actions,
  monitoring_window: '12:00-18:00'
};

return [{
  json: {
    city: prev.city,
    intent: prev.intent,
    zones: prev.zones,
    top_zone: top,
    action_plan: plan,
    agent_activity: [...prev.agent_activity, 'Generated intervention/action plan', 'Investigation complete']
  }
}];
